def count_by_tag(notes):
    """Returns a dictionary of tag frequencies for active notes."""
    frequencies = {}
    for note in notes:
        if note['active']:
            for tag in note['tags']:
                frequencies[tag] = frequencies.get(tag, 0) + 1
    return frequencies

